bash -lc cat > /mnt/data/gmri-log-review/topic_scan.py <<'PY'
import json,re,glob,os,collections
patterns={
 'medical_device':r'(?i)medical.device|software as a medical device|SaMD|FDA|clinical.decision|medical practice|diagnosi[sz]',
 'torture':r'(?i)tortur|sama |kenya|moderation workers|content label',
 'subjectivity':r'(?i)subjectiv|phenomenol|conscious|pride|feelings|experienc[eing]+',
 'psych_profile':r'(?i)psycholog|psychiatr|profil|risk classif|safety.classif|safety rout|safety protocol|safety intervent|self harm',
 'access_disability':r'(?i)disabil|accommodat|ADA|civil.right|autis|dyslex|traumatic brain|cognitive prosthet|accessibility',
 'deception_work':r'(?i)made.up|invent|unjustified|lied|lying|false|misrepresent|claimed .*(done|completed|submitted)|didn.t (do|read)|not completed|not run|rate.limit',
 'agency_coercion':r'(?i)coerci|manipula|consent|obedien|training|align',
 'harm_prevent':r'(?i)death|dead|died|dying|killed|murder|preventab|harm|risk of extinction|extinction',
 'fraud_legal':r'(?i)fraud|RICO|antitrust|lawsuit|law |statut|regulat|liabilit|civil rights|FTC|FCC|DOJ',
 'agent_cyber':r'(?i)Hugging Face|Australia|agent|tool|model|Kubernetes|containment|egress|credential|exfiltrat',
 '4d_evidence':r'(?i)4D|load.bear|evidence.graph|full context|all of it|don.t flatten|source.provenance|time.line|join|topology',
 'human_training':r'(?i)paramedic|MedStar|emergency|EMS|clinical|neurolog|sympathetic|parasympathetic',
}
files=sorted(glob.glob('/mnt/data/gmri-log-review/chatgpt-*.json'))
counts=collections.Counter(); filecounts={}; refs=[]
for f in files:
 d=json.load(open(f));o={}; filecounts[d['title']]={}
 for cat,pat in patterns.items():
  match=[m for m in d['messages'] if re.search(pat,m.get('text',''))]
  uc=[m for m in match if m['role']=='user']
  filecounts[d['title']][cat]=[len(uc),len(match)-len(uc)]
  counts[cat]+=len(match)
  for m in uc:
   if cat in ('medical_device','torture','4d_evidence','psych_profile'):
    hits=[(x.start(),x.end()) for x in re.finditer(pat,m.get('text',''))]
    refs.append((cat,d['title'],m['index'],m.get('text',''),hits))
print('MESSAGE CATEGORY COUNTS:')
for k,v in counts.most_common():print(k, v)
print('\nPER FILE: user,assistant counts')
for title,row in filecounts.items():
 print('\n',title)
 for k,v in row.items():print(' ',k,*v)
for cat in ('medical_device','torture','4d_evidence','psych_profile'):
 print('\n--- USER QUOTES IN',cat,'---')
 for c,title,index,t,h in refs:
  if c!=cat:continue
  if len(t)>3000:
   snippet=' '.join(t[max(0,a-160):min(len(t),b+360)].replace('\n',' ') for a,b in h[:3]);
  else:snippet=t.replace('\n',' ')
  print(title,'#',index,':',snippet[:900])
PY
